import type { CSSProperties, ReactNode, Ref } from "react";
import { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import { ChevronLeft, ChevronRight } from "lucide-react";
import { cn } from "../../lib/cn";
// 书页的结构样式（book-stage / book3d / page-sheet / page-fit）和知识书共用一套，
// 保证每个「书」长得一模一样。
import "../knowledge/knowledge.css";

/**
 * 通用翻书壳 —— 知识书阅读器的翻页机制抽出来的一层：
 *
 * - 一开始是一本合着的书：封面单独一面朝上，点一下翻开；
 * - 翻开后是一张张对开的纸：每翻一张，左右两页同时换成新内容；
 * - 翻到最后再往后翻 = 合上书：封底单独一面朝上，点一下还能再翻开；
 * - 页面不上下滚动：内容由调用方预分页，这里再按页量高缩排（[data-fit]）。
 *
 * 调用方给三层东西：实体页数组（2k 左 / 2k+1 右）、封面/封底的正面内容、
 * 底部状态条的中段文字。翻页、键盘、手势、版面自适应都封在这层里。
 */

type Phase = "closed" | "open" | "back";

type LeafTurn = {
  dir: 1 | -1;
  from: number;
  to: number;
  single: boolean;
  // cover：翻开封面；close：读到最后一页把书合上；reopen：从封底再翻开
  special?: "cover" | "close" | "reopen";
};

export interface FlipBookHandle {
  /** 翻到第 index 张纸（窄屏是第 index 页）；返回 false 表示当前状态到不了。 */
  flipTo: (index: number) => boolean;
  /** 往后翻一张；已经在最后一页还往后翻 = 把书合上（封底朝上）。 */
  next: () => void;
  /** 往前翻一张；封底朝上时往前翻 = 再翻开。 */
  prev: () => void;
  /** 回目录（第 0 张纸）。 */
  goToc: () => void;
  /** 当前摊开的位置。 */
  position: () => number;
  /** 一共几张纸。 */
  total: () => number;
  /** 现在是窄屏单页模式吗（外面算页号时要用）。 */
  isSingle: () => boolean;
}

export interface FlipBookProps {
  /** 实体页：2k 是左页、2k+1 是右页（窄屏一次一页）。奇数张会自动补一页空白保持对开。 */
  pages: ReactNode[];
  /** 封面正面的内容（shell 套 .book-cover__face 的壳）。 */
  cover: ReactNode;
  /** 封底正面的内容。 */
  backCover: ReactNode;
  /** 主题色（--book-accent / --book-secondary）。 */
  accent?: string;
  secondary?: string;
  /** 左上角返回按钮；不传就不显示。 */
  onExit?: () => void;
  exitLabel?: string;
  /** 底部状态条中段：章节名 / 书名等。默认显示「第 n 张 / 共 m 张」。 */
  statusLabel?: ReactNode;
  /** 目录按钮：null 不显示，字符串自定义文案。 */
  tocLabel?: string | null;
  /** 底部状态条里的额外操作（换成这本、收录新词、复习……）。 */
  actions?: ReactNode;
  /** 摊开的位置变了（翻页、跳页都会报）：窄屏是页号，宽屏是纸号。 */
  onPositionChange?: (index: number) => void;
  /** 初始摊开的位置。 */
  initialIndex?: number;
  className?: string;
  ref?: Ref<FlipBookHandle>;
}

const SINGLE_QUERY = "(max-width: 980px)";

export function FlipBook({
  pages,
  cover,
  backCover,
  accent,
  secondary,
  onExit,
  exitLabel = "返回",
  statusLabel,
  tocLabel = "目录",
  actions,
  onPositionChange,
  initialIndex = 0,
  className,
  ref,
}: FlipBookProps) {
  // 对开模式下 pages 必须成对：奇数张补一页，保证最后一张纸有正面也有背面。
  const list = pages.length % 2 === 1 ? [...pages, null] : pages;

  // phase = 书的状态：closed 合着（封面朝上）→ open 翻开 → back 读完合上（封底朝上）。
  const [phase, setPhase] = useState<Phase>("closed");
  const [spread, setSpread] = useState(
    () => Math.max(0, Math.floor(initialIndex)),
  );
  const [pageIndex, setPageIndex] = useState(
    () => Math.max(0, Math.floor(initialIndex)),
  );
  const [single, setSingle] = useState(
    () => typeof window !== "undefined" && window.matchMedia(SINGLE_QUERY).matches,
  );
  const [turn, setTurn] = useState<LeafTurn | null>(null);
  const turnRef = useRef<LeafTurn | null>(null);
  const bookRef = useRef<HTMLDivElement | null>(null);

  const totalLeaves = single ? list.length : Math.ceil(list.length / 2);
  const position = single ? pageIndex : spread;
  const safePos = totalLeaves
    ? Math.min(Math.max(position, 0), totalLeaves - 1)
    : 0;

  // 静态展示的两页：翻页动画进行中，翻去的方向决定哪一边先换成新内容。
  const staticLeftPos = !turn ? safePos : turn.dir === 1 ? turn.from : turn.to;
  const staticRightPos = !turn ? safePos : turn.dir === 1 ? turn.to : turn.from;
  const staticLeftPage = single ? undefined : list[2 * staticLeftPos];
  const staticRightPage = single ? list[safePos] : list[2 * staticRightPos + 1];

  // 翻动的那张纸：正面 = 抬起来的那页，背面 = 落到左边的那页。
  const faceFront = !turn
    ? undefined
    : single
      ? list[turn.dir === 1 ? turn.from : turn.to]
      : list[2 * (turn.dir === 1 ? turn.from : turn.to) + 1];
  const faceBack =
    !turn || single ? undefined : list[2 * (turn.dir === 1 ? turn.to : turn.from)];

  // 打开封面：封面那张纸从右边翻到左边，背面（封里）正好落在左页上。
  const openBook = useCallback(() => {
    if (phase !== "closed" || turnRef.current || !list.length) return;
    if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      setPhase("open");
      return;
    }
    const leaf: LeafTurn = { dir: 1, from: 0, to: 0, single, special: "cover" };
    turnRef.current = leaf;
    setTurn(leaf);
  }, [phase, list.length, single]);

  // 读到最后一页再往后翻 = 把书合上：最后一张纸翻过去，背面就是封底。
  // 窄屏单页不做翻纸动画，直接换到封底那一面。
  const closeBook = useCallback(() => {
    if (phase !== "open" || turnRef.current || !list.length) return;
    if (single || window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      setPhase("back");
      return;
    }
    const from = single ? pageIndex : spread;
    const leaf: LeafTurn = { dir: 1, from, to: from, single, special: "close" };
    turnRef.current = leaf;
    setTurn(leaf);
  }, [phase, list.length, single, pageIndex, spread]);

  // 从封底再翻开：封底那张纸摆回右边，回到最后一对页。
  const reopenFromBack = useCallback(() => {
    if (phase !== "back" || turnRef.current || !list.length) return;
    if (single || window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
      setPhase("open");
      return;
    }
    const from = single ? pageIndex : spread;
    const leaf: LeafTurn = { dir: -1, from, to: from, single, special: "reopen" };
    turnRef.current = leaf;
    setTurn(leaf);
  }, [phase, list.length, single, pageIndex, spread]);

  const beginTurn = useCallback(
    (to: number, dir: 1 | -1) => {
      if (turnRef.current || !list.length) return;
      // 书还合着：往后翻的动作都先变成翻开封面；封底朝上时向左翻 = 再翻开。
      if (phase === "closed") {
        openBook();
        return;
      }
      if (phase === "back") {
        if (dir === -1) reopenFromBack();
        return;
      }
      const from = single ? pageIndex : spread;
      // 翻到最后一对页还往后翻：合上书。
      if (dir === 1 && from === totalLeaves - 1) {
        closeBook();
        return;
      }
      if (to === from || to < 0 || to >= totalLeaves) return;
      if (window.matchMedia("(prefers-reduced-motion: reduce)").matches) {
        if (single) setPageIndex(to);
        else setSpread(to);
        return;
      }
      const leaf: LeafTurn = { dir, from, to, single };
      turnRef.current = leaf;
      setTurn(leaf);
      // 前进：先把新页垫到下面（被翻动的纸盖住），翻完即无缝；后退：翻到落位再换。
      if (dir === 1) {
        if (single) setPageIndex(to);
        else setSpread(to);
      }
    },
    [
      list.length,
      phase,
      openBook,
      reopenFromBack,
      closeBook,
      single,
      pageIndex,
      spread,
      totalLeaves,
    ],
  );

  const endTurn = useCallback(() => {
    const leaf = turnRef.current;
    if (!leaf) return;
    turnRef.current = null;
    setTurn(null);
    if (leaf.special === "cover" || leaf.special === "reopen") {
      setPhase("open");
      return;
    }
    if (leaf.special === "close") {
      setPhase("back");
      return;
    }
    if (leaf.dir === -1) {
      if (leaf.single) setPageIndex(leaf.to);
      else setSpread(leaf.to);
    }
  }, []);

  // 兜底：万一动画事件没到（切后台等），1.4s 后也要落位。
  useEffect(() => {
    if (!turn) return;
    const timer = window.setTimeout(() => endTurn(), 1400);
    return () => window.clearTimeout(timer);
  }, [turn, endTurn]);

  const flipRef = useRef<(dir: 1 | -1) => void>(() => {});
  flipRef.current = (dir) => {
    beginTurn((single ? pageIndex : spread) + dir, dir);
  };

  // 外部控制：翻到指定位置 / 回目录（只在对开状态下有效，和翻页箭头同一套落位规则）。
  useLayoutEffect(() => {
    if (!ref) return;
    const handle: FlipBookHandle = {
      flipTo: (index) => {
        if (phase !== "open" || turnRef.current) return false;
        const from = single ? pageIndex : spread;
        const to = Math.min(Math.max(Math.round(index), 0), totalLeaves - 1);
        if (to === from) return true;
        beginTurn(to, to > from ? 1 : -1);
        return true;
      },
      next: () => flipRef.current(1),
      prev: () => flipRef.current(-1),
      goToc: () => {
        handle.flipTo(0);
      },
      position: () => (single ? pageIndex : spread),
      total: () => totalLeaves,
      isSingle: () => single,
    };
    if (typeof ref === "function") ref(handle);
    else ref.current = handle;
  }, [ref, phase, single, pageIndex, spread, totalLeaves, beginTurn]);

  // 键盘翻页：输入框里打字不算。
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.metaKey || event.ctrlKey || event.altKey || event.defaultPrevented)
        return;
      const target = event.target as HTMLElement | null;
      if (
        target &&
        (target.tagName === "INPUT" ||
          target.tagName === "TEXTAREA" ||
          target.tagName === "SELECT" ||
          target.isContentEditable)
      ) {
        return;
      }
      if (event.key === "ArrowRight") flipRef.current(1);
      else if (event.key === "ArrowLeft") flipRef.current(-1);
    };
    window.addEventListener("keydown", onKeyDown);
    return () => window.removeEventListener("keydown", onKeyDown);
  }, []);

  // 横向划动也算翻页（竖着划留给页内控件）。
  const dragRef = useRef<{
    pointerId: number;
    x: number;
    y: number;
    lastX?: number;
    lastY?: number;
    moved: boolean;
  } | null>(null);

  // 窄屏/宽屏切换：收起翻页动画，把位置对齐到同一条内容上。
  const modeRef = useRef(single);
  useEffect(() => {
    const media = window.matchMedia(SINGLE_QUERY);
    const onChange = () => {
      turnRef.current = null;
      setTurn(null);
      setSingle(media.matches);
    };
    media.addEventListener("change", onChange);
    return () => media.removeEventListener("change", onChange);
  }, []);

  useLayoutEffect(() => {
    if (modeRef.current === single) return;
    modeRef.current = single;
    if (single) {
      setPageIndex(Math.min(2 * spread + 1, Math.max(0, list.length - 1)));
    } else {
      setSpread(Math.floor(pageIndex / 2));
    }
  }, [single, spread, pageIndex, list.length]);

  // 版面自适应：量一量每个页槽里的内容，高的按比例缩到装得下（最多缩到 0.62）。
  const fitScales = useRef(new Map<string, number>());
  const applyFit = useCallback(() => {
    const root = bookRef.current;
    if (!root) return;
    root.querySelectorAll<HTMLElement>("[data-fit]").forEach((el) => {
      const key = el.dataset.fit;
      if (!key) return;
      const parent = el.parentElement;
      if (!parent) return;
      el.style.zoom = "";
      const known = fitScales.current.get(key);
      if (known !== undefined) {
        if (known < 1) el.style.zoom = String(known);
        return;
      }
      const styles = window.getComputedStyle(parent);
      const available =
        parent.clientHeight -
        (Number.parseFloat(styles.paddingTop) || 0) -
        (Number.parseFloat(styles.paddingBottom) || 0);
      const needed = el.scrollHeight + 2;
      if (available < 40 || needed < 40) return; // 还没布局（jsdom / 隐藏页）
      const scale =
        needed <= available ? 1 : Math.max(0.62, (available - 4) / needed);
      fitScales.current.set(key, scale);
      if (scale < 1) el.style.zoom = String(scale);
    });
  }, []);

  useLayoutEffect(() => {
    applyFit();
  }, [applyFit, safePos, turn, single, list.length]);

  useEffect(() => {
    let disposed = false;
    const refit = () => {
      if (!disposed) applyFit();
    };
    if (document.fonts?.ready) {
      void document.fonts.ready
        .then(() => {
          fitScales.current.clear();
          refit();
        })
        .catch(() => {});
    }
    const onResize = () => {
      fitScales.current.clear();
      refit();
    };
    window.addEventListener("resize", onResize);
    return () => {
      disposed = true;
      window.removeEventListener("resize", onResize);
    };
  }, [applyFit]);

  // 位置变化通知外面（联动高亮、滚动等）。
  const reportedRef = useRef(-1);
  useEffect(() => {
    if (!onPositionChange || !totalLeaves) return;
    if (reportedRef.current === safePos) return;
    reportedRef.current = safePos;
    onPositionChange(safePos);
  }, [onPositionChange, safePos, totalLeaves]);

  const coverFace = <div className="book-cover__face">{cover}</div>;
  const backCoverFace = (
    <div className="book-cover__face book-cover__face--back">{backCover}</div>
  );

  return (
    <main
      className={cn("book-stage", className)}
      style={
        {
          "--book-accent": accent,
          "--book-secondary": secondary,
        } as CSSProperties
      }
    >
      {onExit ? (
        <button
          type="button"
          className="book-stage__back"
          onClick={onExit}
          aria-label={exitLabel}
          title={exitLabel}
        >
          <ChevronLeft size={18} />
        </button>
      ) : null}

      <button
        type="button"
        className="book-stage__flip book-stage__flip--prev"
        onClick={() => beginTurn((single ? pageIndex : spread) - 1, -1)}
        disabled={phase === "closed" || (phase === "open" && safePos <= 0)}
        aria-label="上一页"
      >
        <ChevronLeft size={18} />
      </button>
      <button
        type="button"
        className="book-stage__flip book-stage__flip--next"
        onClick={() => beginTurn((single ? pageIndex : spread) + 1, 1)}
        disabled={phase === "back"}
        aria-label="下一页"
      >
        <ChevronRight size={18} />
      </button>

      <div
        className="book-stage__scene"
        onPointerDown={(event) => {
          dragRef.current = {
            pointerId: event.pointerId,
            x: event.clientX,
            y: event.clientY,
            moved: false,
          };
        }}
        onPointerMove={(event) => {
          const drag = dragRef.current;
          if (!drag || drag.pointerId !== event.pointerId) return;
          drag.moved =
            drag.moved ||
            Math.abs(event.clientX - drag.x) > 6 ||
            Math.abs(event.clientY - drag.y) > 6;
          drag.lastX = event.clientX;
          drag.lastY = event.clientY;
        }}
        onPointerUp={(event) => {
          const drag = dragRef.current;
          dragRef.current = null;
          if (!drag || drag.pointerId !== event.pointerId) return;
          const dx = (drag.lastX ?? drag.x) - drag.x;
          const dy = (drag.lastY ?? drag.y) - drag.y;
          // 抬手才算数：横着划出去一截才是翻页，竖着划不算。
          if (Math.abs(dx) < 64 || Math.abs(dx) < Math.abs(dy) * 1.4) return;
          if (drag.moved) flipRef.current(dx < 0 ? 1 : -1);
        }}
        onPointerCancel={() => {
          dragRef.current = null;
        }}
      >
        <div
          className={cn(
            "book3d",
            single && "book3d--single",
            phase === "closed" && !turn && "book3d--closed",
            phase === "back" && !turn && "book3d--closed-back",
            (phase === "open" || turn?.special === "close") && "book3d--opened",
          )}
          ref={bookRef}
        >
          {!single && (phase === "open" || turn?.special === "close") ? (
            <div className="book3d__spine" aria-hidden />
          ) : null}

          {!single &&
          (phase === "open" ||
            turn?.special === "close" ||
            turn?.special === "reopen") ? (
            <section className="book3d__page book3d__page--left" aria-label="左页">
              {staticLeftPage}
            </section>
          ) : null}

          {phase === "closed" && !turn ? (
            <button
              type="button"
              className="book-cover"
              onClick={openBook}
              aria-label="翻开封面"
            >
              {coverFace}
            </button>
          ) : null}
          {phase === "back" && !turn ? (
            <button
              type="button"
              className="book-cover book-cover--back"
              onClick={reopenFromBack}
              aria-label="再翻开这本书"
            >
              {backCoverFace}
            </button>
          ) : null}
          {phase === "open" || turn ? (
            <section className="book3d__page book3d__page--right" aria-label="右页">
              {staticRightPage}
            </section>
          ) : null}

          {turn ? (
            <div
              className={cn(
                "page-sheet",
                turn.dir === 1 ? "page-sheet--fwd" : "page-sheet--bwd",
              )}
              onAnimationEnd={(event) => {
                if (event.target === event.currentTarget) endTurn();
              }}
              aria-hidden
            >
              <div className="page-sheet__face page-sheet__face--front">
                {turn.special === "cover" ? coverFace : faceFront}
              </div>
              <div className="page-sheet__face page-sheet__face--back">
                {turn.special === "close" || turn.special === "reopen"
                  ? backCoverFace
                  : faceBack}
              </div>
            </div>
          ) : null}
        </div>
      </div>

      {/* 底部：回目录 + 当前章节 + 翻到第几页 */}
      <div className="book-stage__status">
        {tocLabel ? (
          <button
            type="button"
            className="book-stage__toc"
            onClick={() => beginTurn(0, safePos > 0 ? -1 : 1)}
          >
            {tocLabel}
          </button>
        ) : null}
        {statusLabel === null ? null : (
          <>
            <span className="book-stage__status-chapter">
              {statusLabel ?? "轻点封面翻开"}
            </span>
            <span className="book-stage__status-sep" aria-hidden />
          </>
        )}
        {actions ? (
          <>
            <span className="book-stage__actions">{actions}</span>
            <span className="book-stage__status-sep" aria-hidden />
          </>
        ) : null}
        <button
          type="button"
          className="book-stage__status-count"
          onClick={() => {
            if (phase === "open" && !turn && safePos < totalLeaves - 1) {
              flipRef.current(1);
            }
          }}
        >
          {safePos + 1} / {Math.max(totalLeaves, 1)}
        </button>
      </div>
    </main>
  );
}
